(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const mx = x+w1x, my = y+w1y;
  const w2x = Math.sin(mx*0.025+t*0.15)*8 + Math.cos(my*0.03-t*0.1)*6;
  const w2y = Math.cos(my*0.028-t*0.12)*8 + Math.sin(mx*0.022+t*0.18)*6;
  const sx = mx+w2x, sy = my+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,0.7],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,0.8],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,0.6],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,0.9],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,0.5],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,0.75],
    [80+Math.sin(t*0.45+3)*110,40+Math.cos(t*0.65+2)*60,0.11,2.1,0.65],
    [400+Math.cos(t*0.55+1)*70,200+Math.sin(t*0.75+4)*50,0.085,1.8,0.85]
  ];
  let aS=0,iS=0,mS=0;
  for(const[sX,sY,f,sp,w]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp)*w;
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    mS+=Math.sin(d*f*0.5-t*sp*0.4+3.0)*w;
  }
  const wT=src.reduce((s,p)=>s+p[4],0);
  const act=aS/wT,inh=iS/wT,mod=mS/wT;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    +Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2
    +Math.sin(sx*0.06+t*0.4)*Math.cos(sy*0.05-t*0.3)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4
    +Math.sin(dist*0.03-ang*5+t*0.8)*0.2;
  const v2x=340+Math.sin(t*0.2)*60,v2y=80+Math.cos(t*0.15)*40;
  const d2=Math.sqrt((sx-v2x)**2+(sy-v2y)**2),a2=Math.atan2(sy-v2y,sx-v2x);
  const vortex2=Math.sin(d2*0.06-a2*4+t*1.8)*0.25;
  const v3x=100+Math.cos(t*0.18)*50,v3y=180+Math.sin(t*0.22)*45;
  const d3=Math.sqrt((sx-v3x)**2+(sy-v3y)**2),a3=Math.atan2(sy-v3y,sx-v3x);
  const vortex3=Math.sin(d3*0.055+a3*3-t*1.4)*0.2;
  const reaction=Math.tanh((act-inh*0.7+mod*0.3+bg*0.25+spiral+vortex2+vortex3)*2.0);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const micro=Math.sin(sx*0.3+t*3)*Math.sin(sy*0.28-t*2.5)*0.06;
  const blend=reaction*0.65+cell*0.25+micro*0.1;
  const v=blend*0.5+0.5;
  const hueShift=Math.sin(t*0.08)*0.08;
  const TAU=6.28318;
  const r0=0.5+0.5*Math.cos(TAU*(1.0*(v+hueShift)+0.0));
  const g0=0.5+0.45*Math.cos(TAU*(0.7*(v+hueShift)+0.12));
  const b0=0.5+0.5*Math.cos(TAU*(0.4*(v+hueShift)+0.22));
  const lum=0.82+Math.sin(reaction*Math.PI)*0.18;
  const edge=Math.abs(reaction)>0.6?1.1:1.0;
  const glow=Math.max(0,reaction)*0.12;
  const highlight=Math.max(0,reaction-0.5)*2*Math.sin(t*2)*0.05;
  return[
    Math.min(255,((r0+glow*0.4+highlight)*lum*edge*255)|0),
    Math.min(255,((g0+glow*0.25+highlight*0.5)*lum*edge*255)|0),
    Math.min(255,((b0+glow*0.15)*lum*edge*255)|0)
  ];
}
